using System;
using System.Collections.Generic;

namespace Astrea;

[Serializable]
public class RuntimeCompanion
{
	public CompanionData CompanionData;

	public int CompanionLevel;

	public int CurrentCorruption;

	public List<StartingEffect> StartingEffects = new List<StartingEffect>();

	public List<StartingEffect> StartingEffectsAdded = new List<StartingEffect>();

	public void SetCompanionData(CompanionData companionData)
	{
		CompanionData = companionData;
	}

	public void SetCompanionLevel(int companionLevel)
	{
		CompanionLevel = companionLevel;
	}

	public void SetCurrentCorruption(int currentCorruption)
	{
		CurrentCorruption = currentCorruption;
	}

	public void AddStartingEffect(StartingEffect startingEffect)
	{
		StartingEffectsAdded.Add(startingEffect);
	}

	public List<StartingEffect> GetStartingEffects(int level)
	{
		return CompanionData.GetCompanionLevels()[level].StartingEffects.DuplicateAsList();
	}

	public List<StartingEffect> GetCombinedEffects()
	{
		List<StartingEffect> list = new List<StartingEffect>();
		_ = StartingEffects;
		for (int i = 0; i < StartingEffects.Count; i++)
		{
			StartingEffect startingEffect = StartingEffects[i];
			list.Add(new StartingEffect(startingEffect.Effect, startingEffect.EffectAmount));
		}
		_ = StartingEffectsAdded;
		for (int j = 0; j < StartingEffectsAdded.Count; j++)
		{
			bool flag = false;
			StartingEffect startingEffect2 = StartingEffectsAdded[j];
			for (int k = 0; k < list.Count; k++)
			{
				StartingEffect startingEffect3 = list[k];
				if (startingEffect2.Effect == startingEffect3.Effect)
				{
					startingEffect3.IncreaseEffectAmount(startingEffect2.EffectAmount);
					flag = true;
				}
			}
			if (!flag)
			{
				list.Add(new StartingEffect(startingEffect2.Effect, startingEffect2.EffectAmount));
			}
		}
		return list;
	}

	public void UpdateStartingEffectsCompanionUpgraded(int newLevel)
	{
		StartingEffects = GetStartingEffects(newLevel);
	}

	public RuntimeCompanion(RuntimeCompanion runtimeCompanion)
	{
		CompanionData = runtimeCompanion.CompanionData;
		CompanionLevel = runtimeCompanion.CompanionLevel;
		CurrentCorruption = 0;
		StartingEffects = runtimeCompanion.StartingEffects.Duplicate();
		StartingEffectsAdded = runtimeCompanion.StartingEffectsAdded.Duplicate();
	}

	public RuntimeCompanion(CompanionData companionData, int companionLevel)
	{
		CompanionData = companionData;
		CompanionLevel = companionLevel;
		CurrentCorruption = 0;
		StartingEffects = companionData.GetCompanionLevels()[companionLevel].StartingEffects.DuplicateAsList();
		StartingEffectsAdded = new List<StartingEffect>();
	}

	public RuntimeCompanion(CompanionData companionData, int companionLevel, List<StartingEffect> startingEffects, List<StartingEffect> startingEffectsAdded)
	{
		CompanionData = companionData;
		CompanionLevel = companionLevel;
		CurrentCorruption = 0;
		StartingEffects = startingEffects.Duplicate();
		StartingEffectsAdded = startingEffectsAdded.Duplicate();
	}
}
